using System;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Windows.Forms;
namespace PZ3D {
 sealed partial class MainForm {
  ShaderSelection shaderStore;DataGridView shaderGrid;Label shaderNotice;TextBox shaderDetails;TabControl toolTabs;DateTime shaderPoll=DateTime.MinValue;
  string DefaultShaderMarker{get{return Path.Combine(UserDir(),".orange-eclipse-default-v3.txt");}}
  string HelpPreference{get{return Path.Combine(data,"startup-help-hidden.txt");}}
  void SetupShaderPage(TabControl tabs){toolTabs=tabs;var page=tabs.TabPages[2];page.Text="光影列表";page.Controls.Clear();var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=4,Padding=new Padding(12)};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,55));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,72));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,45));page.Controls.Add(layout);
   shaderNotice=new Label{Dock=DockStyle.Fill,AutoEllipsis=true};layout.Controls.Add(shaderNotice);shaderGrid=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,BackgroundColor=card,EnableHeadersVisualStyles=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false,ColumnHeadersHeightSizeMode=DataGridViewColumnHeadersHeightSizeMode.AutoSize,RowTemplate={Height=34}};
   shaderGrid.Columns.Add(new DataGridViewTextBoxColumn{HeaderText="光影名称",Width=500});shaderGrid.Columns.Add(new DataGridViewTextBoxColumn{HeaderText="选择状态",Width=260});shaderGrid.Columns.Add(new DataGridViewTextBoxColumn{HeaderText="类型 / 说明",AutoSizeMode=DataGridViewAutoSizeColumnMode.Fill});layout.Controls.Add(shaderGrid);shaderDetails=new TextBox{Dock=DockStyle.Fill,ReadOnly=true,Multiline=true,ScrollBars=ScrollBars.Vertical};layout.Controls.Add(shaderDetails);
   var actions=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=true};actions.Controls.Add(Button("启用所选光影（先退出游戏）",SelectShader));actions.Controls.Add(Button("刷新列表",RefreshShaderSelection));actions.Controls.Add(Button("导入光影 ZIP",()=>{using(var d=new OpenFileDialog{Filter="光影 ZIP|*.zip"})if(d.ShowDialog()==DialogResult.OK){string zip=d.FileName;Run(()=>GetEngine().Import(zip));}}));actions.Controls.Add(Button("打开实际光影目录",()=>{Directory.CreateDirectory(GetEngine().ShaderDir);Links.Open(GetEngine().ShaderDir);}));layout.Controls.Add(actions);shaderGrid.ColumnHeadersDefaultCellStyle.ForeColor=fg;
   shaderGrid.SelectionChanged+=(s,e)=>{if(shaderGrid.CurrentRow==null)return;var p=shaderGrid.CurrentRow.Tag as ShaderChoice;if(p!=null)shaderDetails.Text=p.Description+"\r\n实际 ID："+p.Id+"\r\n文件："+(p.File??"Viewpoint 自带，无需额外 ZIP")+"\r\n同一时间只选择一套光影；保存后重启游戏。";};Theme(page);RefreshShaderSelection();
  }
  void RefreshShaderSelection(){if(shaderGrid==null)return;try{string highlighted=shaderGrid.CurrentRow==null?null:((ShaderChoice)shaderGrid.CurrentRow.Tag).Id;shaderStore=new ShaderSelection(UserDir(),Path.Combine(data,"settings-backups"));shaderGrid.Rows.Clear();foreach(var p in shaderStore.Packs){int row=shaderGrid.Rows.Add(p.Name,p.Id==shaderStore.Selected?"已选择（下次启动）":p.Valid?"未选择":"不可启用",p.Id==ShaderSelection.Eclipse?"Viewpoint 3D 专用适配 · 工具默认":p.File==null?"Viewpoint 内置":"Minecraft / Iris · 实验兼容");shaderGrid.Rows[row].Tag=p;if(p.Id==shaderStore.Selected)shaderGrid.Rows[row].DefaultCellStyle.ForeColor=Color.FromArgb(255,190,55);if(p.Id==highlighted)shaderGrid.CurrentCell=shaderGrid.Rows[row].Cells[0];}
    shaderNotice.Text="配置中的光影："+(shaderStore.Selected.Length==0?"尚未选择；首次安装默认 Eclipse":shaderStore.Selected)+"\n列表显示已安装包；不代表游戏已成功编译或正在渲染。首次安装默认 Eclipse，之后保留玩家选择。";
   }catch(Exception e){shaderNotice.Text="读取光影列表失败，未修改文件："+e.Message;}}
  void PollShaders(){if(shaderGrid==null||busy||(DateTime.Now-shaderPoll).TotalSeconds<2)return;shaderPoll=DateTime.Now;if(shaderGrid.ContainsFocus)return;RefreshShaderSelection();}
  void SelectShader(){if(shaderGrid.CurrentRow==null||shaderStore==null)throw new Exception("先选择一套已安装的光影。");if(settingsEdits.Count>0)throw new Exception("中文设置页有未保存编辑，请先保存或放弃，避免覆盖。");var choice=(ShaderChoice)shaderGrid.CurrentRow.Tag;string result=shaderStore.Select(choice.Id,false);File.WriteAllText(DefaultShaderMarker,choice.Id);RefreshShaderSelection();LoadSettings();Write(result);MessageBox.Show(this,result,"光影选择",MessageBoxButtons.OK,MessageBoxIcon.Information);}
  void JumpToKeys(){toolTabs.SelectedTab=settingsTab;settingsGroup.SelectedItem="快捷键";settingsSearch.Text="";}
  Form CreateStartupDialog(){var dialog=new Form{Text="橙子3D · 开始使用",Icon=Icon,StartPosition=FormStartPosition.CenterParent,Size=new Size(1040,850),MinimumSize=new Size(760,650),BackColor=bg,ForeColor=fg,Font=Font,ShowInTaskbar=false};var layout=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=3,ColumnCount=1,Padding=new Padding(20)};layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,45));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,65));dialog.Controls.Add(layout);var text=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Text=StartupHelp.Body(UserDir())};layout.Controls.Add(text);var hide=new GoldCheckBox{Text="以后不再自动显示（可从使用帮助重新打开）",AutoSize=true,Checked=!StartupHelp.ShouldShow(HelpPreference)};layout.Controls.Add(hide);var actions=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=true};actions.Controls.Add(Button("编辑快捷键",()=>{dialog.Close();JumpToKeys();}));actions.Controls.Add(Button("光影列表",()=>{dialog.Close();toolTabs.SelectedIndex=2;}));var done=Button("知道了，继续",()=>dialog.Close());actions.Controls.Add(done);dialog.AcceptButton=done;dialog.Shown+=(s,e)=>{text.SelectionStart=0;text.SelectionLength=0;done.Focus();};layout.Controls.Add(actions);dialog.FormClosed+=(s,e)=>{if(!Program.PreviewMode)StartupHelp.SetHidden(HelpPreference,hide.Checked);};Theme(dialog);return dialog;}
  void ShowStartupHelp(bool automatic){if(automatic&&!StartupHelp.ShouldShow(HelpPreference))return;using(var dialog=CreateStartupDialog())dialog.ShowDialog(this);}
  public void PreviewHelp(string output){ShowInTaskbar=false;StartPosition=FormStartPosition.Manual;Location=new Point(-2000,-2000);Show();using(var dialog=CreateStartupDialog()){dialog.StartPosition=FormStartPosition.Manual;dialog.Location=new Point(-2000,-2000);dialog.Show();Application.DoEvents();using(var bitmap=new Bitmap(dialog.Width,dialog.Height)){dialog.DrawToBitmap(bitmap,new Rectangle(0,0,dialog.Width,dialog.Height));bitmap.Save(output,System.Drawing.Imaging.ImageFormat.Png);}dialog.Close();}Close();}
 }
}
